Definition z4 : list byte := [b8 0; b8 0; b8 0; b8 0].
Definition z8 : list byte := [b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0].
Definition z12 : list byte := [b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0].
Definition z16 : list byte := [b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0].

Lemma PCond_cells : forall m C clk, PCond m C clk ->
  rw_cells rsegs m C [CB 16 z16; C4 (wz clk); CB 12 z12; C4 (wz 0); CB 4 z4; C8 (wz 0)]
  /\ (clk = 0 \/ clk = CLOCK_MONOTONIC) /\ C mod 8 = 0.
Proof. intros m C clk [PC [CK AL]]. unfold PCondCells, zeros in PC. cbn [repeat] in PC. auto. Qed.

Lemma PCond_fold : forall m C clk,
  rw_cells rsegs m C [CB 16 z16; C4 (wz clk); CB 12 z12; C4 (wz 0); CB 4 z4; C8 (wz 0)] ->
  (clk = 0 \/ clk = CLOCK_MONOTONIC) -> C mod 8 = 0 -> PCond m C clk.
Proof. intros m C clk PC CK AL. split; [| split; [exact CK| exact AL]]. unfold PCondCells, zeros. cbn [repeat]. exact PC. Qed.

(* [comment removed for export] *)
Lemma PCond_fold_sig : forall m C clk,
  rw_cells rsegs m C [CB 8 z8; C8 (Z_to_bv 64 0); C4 (wz clk); CB 12 z12; C4 (Z_to_bv 64 0); CB 4 z4; C8 (Z_to_bv 64 0)] ->
  (clk = 0 \/ clk = CLOCK_MONOTONIC) -> C mod 8 = 0 -> PCond m C clk.
Proof.
  intros m C clk PC CK AL. apply PCond_fold; [| exact CK| exact AL].
  destruct CK as [-> | ->];
    (eapply rw_cells_recells; [exact PC | cbn; repeat split; reflexivity | vm_compute; reflexivity | reflexivity]).
Qed.

(* [comment removed for export] *)
Lemma PCond_fold_init : forall m C clk,
  rw_cells rsegs m C [C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0); C4 (Z_to_bv 64 clk); C4 (Z_to_bv 64 0); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0)] ->
  (clk = 0 \/ clk = CLOCK_MONOTONIC) -> C mod 8 = 0 -> PCond m C clk.
Proof.
  intros m C clk PC CK AL. apply PCond_fold; [| exact CK| exact AL].
  destruct CK as [-> | ->];
    (eapply rw_cells_recells; [exact PC | cbn; repeat split; reflexivity | vm_compute; reflexivity | reflexivity]).
Qed.

Lemma sx32_lit : forall x, 0 <= x < 2^31 -> sx32 (Z_to_bv 64 x) = Z_to_bv 64 x.
Proof. intros x H. exact (sx32_wz x H). Qed.

Lemma amo_aligned_C32 : forall C, 0 <= C -> C + 40 <= 2^64 -> C mod 8 = 0 -> amo_aligned AW (Z_to_bv 64 (C + 32)) = true.
Proof.
  intros C H0 H1 AL. apply amo_aligned_intro; [lia|]. rewrite <- Zplus_mod_idemp_l.
  replace (C mod 4) with 0; [reflexivity|]. Z.div_mod_to_equations; lia.
Qed.

