Definition cv_dtor_post (ra sp gp tp s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (C clk lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a0 a1 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ PCond m' C clk.

Definition cv_dtor_stmt : Prop :=
  forall (C clk lo : Z) ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  PCond m C clk ->
  stk rsegs m lo (bv_unsigned sp) -> lo + CV_DTOR_STACK <= bv_unsigned sp -> hceil <= lo ->
  (C + 48 <= lo \/ bv_unsigned sp <= C) ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (cv_dtor_post ra sp gp tp s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc C clk lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz C) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_CV_DTOR) fc None m (seg_rom rsegs)).

